-- OFFLINE ACL supplement. Apply only inside the sealed migration + owner-read transaction.
-- Object-local rights only. No ALTER DEFAULT PRIVILEGES, role membership or global grant.
do $acl_guard$
begin
  if to_regclass('public.target_sleeve_allocations') is null
     or to_regclass('public.target_sleeve_allocations_id_seq') is null
     or pg_get_serial_sequence('public.target_sleeve_allocations', 'id')::regclass
        is distinct from 'public.target_sleeve_allocations_id_seq'::regclass then
    raise exception 'unexpected sleeve table/sequence binding';
  end if;
  if not exists (select 1 from pg_class
    where oid = 'public.target_sleeve_allocations'::regclass
      and relkind = 'r' and relrowsecurity
      and pg_has_role(current_user, relowner, 'USAGE')) then
    raise exception 'sleeve ACL correction requires its owner and enabled RLS';
  end if;
end
$acl_guard$;

revoke all privileges on table public.target_sleeve_allocations
  from public, anon, authenticated, service_role;
revoke all privileges on sequence public.target_sleeve_allocations_id_seq
  from public, anon, authenticated, service_role;
grant select on table public.target_sleeve_allocations to authenticated;
grant select, insert, update, delete on table public.target_sleeve_allocations to service_role;
grant usage, select on sequence public.target_sleeve_allocations_id_seq to service_role;

do $acl_check$
begin
  if has_table_privilege('anon', 'public.target_sleeve_allocations',
       'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
     or has_table_privilege('authenticated', 'public.target_sleeve_allocations',
       'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
     or not has_table_privilege('authenticated', 'public.target_sleeve_allocations', 'SELECT')
     or has_sequence_privilege('anon', 'public.target_sleeve_allocations_id_seq', 'USAGE,SELECT,UPDATE')
     or has_sequence_privilege('authenticated', 'public.target_sleeve_allocations_id_seq', 'USAGE,SELECT,UPDATE')
     or has_table_privilege('service_role', 'public.target_sleeve_allocations', 'TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
     or not has_table_privilege('service_role', 'public.target_sleeve_allocations', 'SELECT')
     or not has_table_privilege('service_role', 'public.target_sleeve_allocations', 'INSERT')
     or not has_table_privilege('service_role', 'public.target_sleeve_allocations', 'UPDATE')
     or not has_table_privilege('service_role', 'public.target_sleeve_allocations', 'DELETE')
     or not has_sequence_privilege('service_role', 'public.target_sleeve_allocations_id_seq', 'USAGE')
     or not has_sequence_privilege('service_role', 'public.target_sleeve_allocations_id_seq', 'SELECT')
     or has_sequence_privilege('service_role', 'public.target_sleeve_allocations_id_seq', 'UPDATE') then
    raise exception 'unexpected effective sleeve table/sequence privileges';
  end if;
end
$acl_check$;

-- OFFLINE supplement: repair only authenticated ACL on the recreated advice view.
-- Apply with the sealed migration, sleeve ACL supplement and owner-read postlude
-- in the same transaction. No role, default privilege, schema or other object edit.
do $view_acl_guard$
begin
  if not exists (
    select 1 from pg_class
    where oid = to_regclass('public.allocation_advice_items_latest')
      and relkind = 'v' and pg_has_role(current_user, relowner, 'USAGE')
  ) then
    raise exception 'advice view ACL correction requires the expected view owner';
  end if;
end
$view_acl_guard$;

revoke all privileges on table public.allocation_advice_items_latest from authenticated;
grant select on table public.allocation_advice_items_latest to authenticated;

do $view_acl_check$
begin
  if not has_table_privilege('authenticated', 'public.allocation_advice_items_latest', 'SELECT')
     or has_table_privilege('authenticated', 'public.allocation_advice_items_latest',
         'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') then
    raise exception 'unexpected effective authenticated advice view privileges';
  end if;
end
$view_acl_check$;

-- OFFLINE CANDIDATE ONLY. Never run separately from the sealed migration transaction.
-- This narrows one new policy; it does not authorize applying any SQL to Supabase.
do $guard$
begin
  if to_regclass('public.fo_owner_profiles') is null
     or to_regprocedure('auth.uid()') is null then
    raise exception 'registered-owner authorization dependencies are absent';
  end if;
  if not exists (
    select 1 from pg_class where oid = 'public.fo_owner_profiles'::regclass and relrowsecurity
  ) then
    raise exception 'owner profile RLS is not enabled';
  end if;
  if exists (
    select 1 from pg_roles
    where rolname = 'authenticated' and (rolsuper or rolbypassrls)
  ) or pg_has_role('authenticated',
       (select relowner from pg_class where oid = 'public.target_sleeve_allocations'::regclass), 'USAGE') then
    raise exception 'authenticated role can bypass sleeve RLS';
  end if;
  if exists (
    select 1 from pg_policy
    where polrelid = 'public.target_sleeve_allocations'::regclass
      and polcmd in ('r', '*')
      and polname not in ('target_sleeve_allocations_read', 'target_sleeve_allocations_service_role_write')
  ) then
    raise exception 'unexpected sleeve SELECT/ALL policy; stop without rewriting it';
  end if;
  if has_table_privilege('authenticated', 'public.target_sleeve_allocations',
      'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') then
    raise exception 'unexpected authenticated sleeve write grant';
  end if;
end
$guard$;

drop policy if exists target_sleeve_allocations_read on public.target_sleeve_allocations;
create policy target_sleeve_allocations_read on public.target_sleeve_allocations
  for select to authenticated
  using (exists (
    select 1 from public.fo_owner_profiles profile
    where profile.user_id = (select auth.uid())
  ));
-- Other policies, tables, routines and grants are intentionally unchanged.
